CREATE TABLE Positions(Id INT IDENTITY PRIMARY KEY,Title NVARCHAR(200) NOT NULL,MaxScore DECIMAL(10,2) NOT NULL DEFAULT 100);
CREATE TABLE Questions(Id INT IDENTITY PRIMARY KEY,PositionId INT NOT NULL REFERENCES Positions(Id),Text NVARCHAR(1000) NOT NULL,MaxScore DECIMAL(10,2) NOT NULL,SortOrder INT NOT NULL DEFAULT 1);
CREATE TABLE OrgUnits(Id INT IDENTITY PRIMARY KEY,Title NVARCHAR(200) NOT NULL,ParentId INT NULL REFERENCES OrgUnits(Id));
CREATE TABLE Employees(Id INT IDENTITY PRIMARY KEY,PersonnelNo NVARCHAR(50) NOT NULL UNIQUE,FullName NVARCHAR(200) NOT NULL,PositionId INT NOT NULL REFERENCES Positions(Id),UnitId INT NOT NULL REFERENCES OrgUnits(Id),IsEvaluator BIT NOT NULL DEFAULT 0,SupervisorId INT NULL REFERENCES Employees(Id),IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE EvaluationPeriods(Id INT IDENTITY PRIMARY KEY,Title NVARCHAR(100) NOT NULL,StartDatePersian NVARCHAR(10) NOT NULL,EndDatePersian NVARCHAR(10) NOT NULL,StartDate DATETIME2 NOT NULL,EndDate DATETIME2 NOT NULL,IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE Evaluations(Id INT IDENTITY PRIMARY KEY,PeriodId INT NOT NULL REFERENCES EvaluationPeriods(Id),EmployeeId INT NOT NULL REFERENCES Employees(Id),EvaluatorId INT NOT NULL REFERENCES Employees(Id),CreatedAt DATETIME2 NOT NULL,UpdatedAt DATETIME2 NOT NULL,CONSTRAINT UQ_Evaluation UNIQUE(PeriodId,EmployeeId));
CREATE TABLE EvaluationScores(Id INT IDENTITY PRIMARY KEY,EvaluationId INT NOT NULL REFERENCES Evaluations(Id),QuestionId INT NOT NULL REFERENCES Questions(Id),Score DECIMAL(10,2) NOT NULL,Comment NVARCHAR(1000),CONSTRAINT UQ_Score UNIQUE(EvaluationId,QuestionId));
CREATE TABLE EvaluationScoreHistory(Id BIGINT IDENTITY PRIMARY KEY,EvaluationId INT NOT NULL,QuestionId INT NOT NULL,OldScore DECIMAL(10,2) NOT NULL,NewScore DECIMAL(10,2) NOT NULL,ChangedBy INT NOT NULL,ChangedAt DATETIME2 NOT NULL);
CREATE TABLE AuditLogs(Id BIGINT IDENTITY PRIMARY KEY,Action NVARCHAR(100) NOT NULL,Entity NVARCHAR(100) NOT NULL,EntityId NVARCHAR(100) NOT NULL,Details NVARCHAR(MAX),CreatedAt DATETIME2 NOT NULL);